const C = {
  timeScale: 20,
  tank: 20, pRated: 4.2, pIdle: 0.2,
  pumpFlows: { P01: 40, P02: 25 },
  pumpCombos: { P01: { flow: 40, pressure: 4.2 }, P02: { flow: 25, pressure: 2.625 },
    both: { flow: 50, pressure: 5.17 } },
  autoStart: 2,
  inNom: 40,
  maxBlockage: 0.5, blockageRate: 0.01, flowLoss: 0.9,
  pressureHalfLife: 2,
  level: { target: 60, low: 20, lowClear: 25, lowLow: 10, lowLowClear: 30,
    high: 85, highClear: 80, highHigh: 90, highHighClear: 85 },
  pressure: { high: 6, clear: 5.5 }
};
flow.set('simConfig', C);
flow.set('sim', {
  stationId: 'PS01',
  simulation: { time: 0, seed: 42, scenario: 'normal', inflowFactor: 1, lastTickMs: Date.now() },
  tank: { id: 'T01', level: C.level.target },
  pumps: {
    P01: { role: 'main', status: 'Running' },
    P02: { role: 'standby', status: 'Stopped' }
  },
  inlet: { mode: 'normal', flow: C.inNom, limitedFlow: null },
  outlet: { id: 'OUT01', pressure: C.pRated, flow: C.pumpFlows.P01, blockage: 0 },
  controller: { manual: false, interlock: false, faultTimer: 0, faultStartedAtMs: null },
  alarms: { LOW_LEVEL: false, LOW_LOW_LEVEL: false, HIGH_LEVEL: false,
    HIGH_HIGH_LEVEL: false, HIGH_PRESSURE: false, PUMP_FAULT: false }
});
node.status({ fill: 'green', shape: 'dot', text: 'state initialised' });
return null;

const C = flow.get('simConfig');
const s = flow.get('sim');
if (!s || !C) { node.warn('State not initialised'); return null; }
const A = s.alarms;

// Advance the seeded random number generator.
function rnd() {
  s.simulation.seed = (s.simulation.seed + 0x6D2B79F5) | 0;
  let t = s.simulation.seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
// Generate Gaussian measurement noise.
function gauss(sd) {
  const u = 1 - rnd(), v = rnd();
  return sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const round = (x, d) => Math.round(x * 10 ** d) / 10 ** d;

// Increase blockage using simulated seconds, not the number of ticks.
function rampBlockage(dt) {
  if (s.simulation.scenario === 'high_pressure') {
    s.outlet.blockage = Math.min(C.maxBlockage, s.outlet.blockage + C.blockageRate * dt);
  }
}

// Balance the tank using the previous interval's outlet flow.
// The upper limit only reduces inlet flow; it never adds water to hold the level.
function updateTank(dt) {
  const outlet = s.outlet.flow;
  const nominalInlet = Math.max(0, C.inNom * s.simulation.inflowFactor);
  let qin = nominalInlet;
  if (s.inlet.mode === 'recover') {
    qin = Math.min(nominalInlet, Math.max(0, s.inlet.limitedFlow));
  }
  const factor = dt / 3600 / (C.tank * 0.01);
  let next = s.tank.level + (qin - outlet) * factor;
  if (next >= C.level.highHigh) {
    if (factor > 0) {
      const safeInlet = Math.max(0, outlet + (C.level.highHigh - s.tank.level) / factor);
      qin = Math.min(qin, safeInlet);
    }
    next = Math.min(C.level.highHigh, s.tank.level + (qin - outlet) * factor);
    if (s.inlet.mode === 'normal') s.inlet.mode = 'hold';
  } else if (s.inlet.mode === 'recover' && next <= C.level.target) {
    // Finish recovery without exceeding the normal supply to force a level target.
    if (factor > 0 && s.tank.level >= C.level.target) {
      const targetInlet = Math.max(0, outlet + (C.level.target - s.tank.level) / factor);
      qin = Math.min(nominalInlet, targetInlet);
      next = s.tank.level + (qin - outlet) * factor;
    }
    s.inlet.mode = 'normal';
    s.inlet.limitedFlow = null;
  }
  s.inlet.flow = qin;
  s.tank.level = clamp(next, 0, 100);
  return clamp(round(s.tank.level + gauss(0.15), 1), 0, 100);
}

// Evaluate measured level alarms; low-low protection stays latched until refill to 60%.
function evaluateLevelAlarms(lt) {
  if (!A.LOW_LEVEL && lt <= C.level.low) A.LOW_LEVEL = true;
  else if (A.LOW_LEVEL && lt > C.level.lowClear) A.LOW_LEVEL = false;
  if (!A.LOW_LOW_LEVEL && lt <= C.level.lowLow) A.LOW_LOW_LEVEL = true;
  else if (A.LOW_LOW_LEVEL && lt > C.level.lowLowClear) A.LOW_LOW_LEVEL = false;
  if (!A.HIGH_LEVEL && lt >= C.level.high) A.HIGH_LEVEL = true;
  else if (A.HIGH_LEVEL && lt <= C.level.highClear) A.HIGH_LEVEL = false;
  if (!A.HIGH_HIGH_LEVEL && lt >= C.level.highHigh) A.HIGH_HIGH_LEVEL = true;
  else if (A.HIGH_HIGH_LEVEL && lt <= C.level.highHighClear) A.HIGH_HIGH_LEVEL = false;
  if (A.LOW_LOW_LEVEL) s.controller.interlock = true;
}

// Enforce low-level refill and the standby delay measured in real seconds.
function runController(nowMs) {
  if (s.controller.interlock && !A.LOW_LOW_LEVEL &&
      s.simulation.scenario !== 'low_level' && s.tank.level >= C.level.target) {
    s.controller.interlock = false;
    if (!s.controller.manual && s.pumps.P01.status !== 'Fault') s.pumps.P01.status = 'Running';
  }
  if (s.controller.interlock) {
    if (s.pumps.P01.status === 'Running') s.pumps.P01.status = 'Stopped';
    if (s.pumps.P02.status === 'Running') s.pumps.P02.status = 'Stopped';
  }
  if (!s.controller.manual && s.pumps.P01.status === 'Fault' && s.pumps.P02.status === 'Stopped') {
    s.controller.faultTimer = Math.max(0, (nowMs - s.controller.faultStartedAtMs) / 1000);
    if (!s.controller.interlock && !A.LOW_LOW_LEVEL &&
        s.controller.faultTimer >= C.autoStart) {
      s.pumps.P02.status = 'Running';
    }
  }
}

// Choose a calibrated operating point, then apply blockage and pressure response.
function computeOutlet(dt) {
  const p1 = s.pumps.P01.status === 'Running';
  const p2 = s.pumps.P02.status === 'Running';
  const entry = p1 && p2 ? C.pumpCombos.both : p1 ? C.pumpCombos.P01 : p2 ? C.pumpCombos.P02 : null;
  const capacity = entry ? entry.flow : 0;
  s.outlet.flow = capacity * (1 - C.flowLoss * s.outlet.blockage);
  const pTarget = entry ? entry.pressure * (1 + s.outlet.blockage) : C.pIdle;
  s.outlet.pressure += (pTarget - s.outlet.pressure) * (1 - Math.pow(0.5, dt / C.pressureHalfLife));
  const ft = capacity > 0 ? Math.max(0.1, round(s.outlet.flow + gauss(0.4), 1)) : 0;
  const pt = Math.max(0, round(s.outlet.pressure + gauss(0.03), 2));
  return { ft, pt };
}

// Evaluate pressure hysteresis and preserve fault alarms while the standby runs.
function evaluatePressureAndPumpAlarms(pt) {
  if (!A.HIGH_PRESSURE && pt > C.pressure.high) A.HIGH_PRESSURE = true;
  else if (A.HIGH_PRESSURE && pt < C.pressure.clear) A.HIGH_PRESSURE = false;
  A.PUMP_FAULT = Object.values(s.pumps).some(p => p.status === 'Fault');
}

// Publish the existing telemetry shape and one event for each alarm transition.
function buildMessages(lt, out, prev) {
  const { ft, pt } = out;
  const now = new Date().toISOString();
  const info = {
    LOW_LEVEL: { sev: 'warning', tag: 'LT01', val: lt, thr: C.level.low },
    LOW_LOW_LEVEL: { sev: 'critical', tag: 'LT01', val: lt, thr: C.level.lowLow },
    HIGH_LEVEL: { sev: 'warning', tag: 'LT01', val: lt, thr: C.level.high },
    HIGH_HIGH_LEVEL: { sev: 'critical', tag: 'LT01', val: lt, thr: C.level.highHigh },
    HIGH_PRESSURE: { sev: 'warning', tag: 'PT01', val: pt, thr: C.pressure.high },
    PUMP_FAULT: { sev: 'critical' }
  };
  const events = [];
  for (const code of Object.keys(A)) {
    if (A[code] !== prev[code]) {
      const i = info[code];
      const ev = { ts: now, station: s.stationId, code, severity: i.sev, active: A[code] };
      if (i.tag) { ev.tag = i.tag; ev.value = i.val; ev.threshold = i.thr; }
      events.push({ topic: 'plant/ps01/events', payload: ev });
    }
  }
  const tele = {
    topic: 'plant/ps01/telemetry',
    payload: {
      ts: now, station: s.stationId, scenario: s.simulation.scenario,
      tags: {
        LT01: { asset: s.tank.id, value: lt, unit: '%', quality: 'good' },
        PT01: { asset: s.outlet.id, value: pt, unit: 'bar', quality: 'good' },
        FT01: { asset: s.outlet.id, value: ft, unit: 'm3/h', quality: 'good' }
      },
      pumps: {
        P01: { status: s.pumps.P01.status, role: s.pumps.P01.role },
        P02: { status: s.pumps.P02.status, role: s.pumps.P02.role }
      },
      alarms: Object.keys(A).filter(k => A[k])
    }
  };
  flow.set('sim', s);
  node.status({ text: `${s.simulation.scenario} | L=${lt} P=${pt} F=${ft}` });
  return [tele, events];
}

// Scale elapsed real time once; the standby timer uses the unscaled clock.
function tick() {
  const nowMs = Date.now();
  const dt = Math.max(0, nowMs - s.simulation.lastTickMs) / 1000 * C.timeScale;
  s.simulation.lastTickMs = nowMs;
  s.simulation.time += dt;
  const prev = Object.assign({}, A);
  rampBlockage(dt);
  const lt = updateTank(dt);
  evaluateLevelAlarms(lt);
  runController(nowMs);
  const out = computeOutlet(dt);
  evaluatePressureAndPumpAlarms(out.pt);
  return buildMessages(lt, out, prev);
}
return tick();

const payload = msg.payload;
const cmd = payload && payload.scenario;
const valid = ['normal', 'reset', 'low_level', 'high_pressure', 'pump_fault'];
let s = flow.get('sim');
const C = flow.get('simConfig');
if (!s || !C) { node.warn('State not initialised'); return null; }

// Validate and enforce protections before changing any state.
const pumpRequest = payload && typeof payload === 'object' &&
  ('pump' in payload || 'command' in payload);
if (pumpRequest || !valid.includes(cmd)) {
  const pump = payload && payload.pump;
  const command = payload && payload.command;
  if (!pumpRequest || !['P01', 'P02'].includes(pump) ||
      !['run', 'stop', 'fault'].includes(command) || cmd !== undefined) {
    node.warn('Bad pump command: ' + JSON.stringify(payload));
    return null;
  }
  if (command === 'run') {
    if (s.controller.interlock) {
      node.warn('Run rejected: low-level interlock active');
      return null;
    }
    if (s.alarms.LOW_LOW_LEVEL) {
      node.warn('Run rejected: low-low-level alarm active');
      return null;
    }
    const other = pump === 'P01' ? 'P02' : 'P01';
    if ((s.simulation.scenario === 'high_pressure' || s.alarms.HIGH_PRESSURE) &&
        s.pumps[other].status === 'Running') {
      node.warn('Run rejected: high pressure permits only one running pump');
      return null;
    }
  }
  const previous = s.pumps[pump].status;
  s.controller.manual = true;
  s.pumps[pump].status = { run: 'Running', stop: 'Stopped', fault: 'Fault' }[command];
  if (command === 'fault' && previous !== 'Fault') {
    s.controller.faultStartedAtMs = Date.now();
    s.controller.faultTimer = 0;
  } else if (!Object.values(s.pumps).some(p => p.status === 'Fault')) {
    s.controller.faultStartedAtMs = null;
    s.controller.faultTimer = 0;
  }
  flow.set('sim', s);
  node.status({ fill: 'blue', shape: 'dot', text: 'manual: ' + pump + ' ' + command });
  msg.payload = { applied: pump + ' ' + command };
  return msg;
}

// Reset physical state and RNG, retaining alarm flags until their closing events are emitted.
function resetState() {
  return {
    stationId: 'PS01',
    simulation: { time: 0, seed: 42, scenario: 'normal', inflowFactor: 1, lastTickMs: Date.now() },
    tank: { id: 'T01', level: C.level.target },
    pumps: {
      P01: { role: 'main', status: 'Running' },
      P02: { role: 'standby', status: 'Stopped' }
    },
    inlet: { mode: 'normal', flow: C.inNom, limitedFlow: null },
    outlet: { id: 'OUT01', pressure: C.pRated, flow: C.pumpFlows.P01, blockage: 0 },
    controller: { manual: false, interlock: false, faultTimer: 0, faultStartedAtMs: null },
    alarms: s.alarms
  };
}

if (cmd === 'reset') {
  s = resetState();
} else if (cmd !== s.simulation.scenario || cmd === 'normal') {
  if (cmd === 'normal') {
    if (s.inlet.mode === 'hold') {
      s.inlet.mode = 'recover';
      s.inlet.limitedFlow = s.outlet.flow;
    }
  } else {
    s.inlet.mode = 'normal';
    s.inlet.limitedFlow = null;
  }
  s.controller.manual = false;
  s.simulation.scenario = cmd;
  s.simulation.inflowFactor = cmd === 'low_level' ? 25 / C.inNom : 1;
  s.outlet.blockage = 0;
  s.controller.faultTimer = 0;
  s.controller.faultStartedAtMs = cmd === 'pump_fault' ? Date.now() : null;
  // Entering high pressure changes the hydraulics, not the existing pump states.
  // LOW_LOW_LEVEL protection remains enforced by the controller on each tick.
  if (cmd !== 'high_pressure') {
    const lowBlocksStart = s.alarms.LOW_LOW_LEVEL;
    s.pumps.P01.status = cmd === 'pump_fault' ? 'Fault'
      : (s.controller.interlock || lowBlocksStart ? 'Stopped' : 'Running');
    s.pumps.P02.status = 'Stopped';
  }
}
flow.set('sim', s);
node.status({ fill: 'blue', shape: 'dot', text: 'scenario: ' + s.simulation.scenario });
msg.payload = { applied: s.simulation.scenario };
return msg;
